-- Hand-washing cups, mayim acharonim and towels from the supplier (Art Judaica), 226 products, in Hebrew,
-- French and English, as single items for the custom gift box:
-- housewarming-netilah: 201, shabbat-mayim-achronim: 15, housewarming-towels: 10.
-- Price: the supplier's price × 2.5, rounded to the shekel.
-- They come in HIDDEN: in the admin area switch on the ones you want.
-- Run it ONCE: running it again would bring back products you deleted.

insert into public.products
  (id, category, categories, name_he, name_fr, name_en, subtitle_he, subtitle_fr, subtitle_en,
   description_he, description_fr, description_en, price, images, active, in_stock, kind, sort)
values
  ('art-UK67553', 'housewarming', array['housewarming','housewarming-netilah','judaica']::text[],
   'נטלה מהודרת מפולימר 14 ס"מ', 'Netla raffinée en polymère 14 cm', 'Elegant polymer washing cup 14 cm',
   'פולימר · 15 × 14 ס״מ', 'polymère · 15 × 14 cm', 'polymer · 15 × 14 cm',
   'נטלה מהודרת מפולימר, בגובה 14 ס"מ, משלבת יופי ונוחות. עיצובה הייחודי עם חמסות ותפילה מוסיף טאץ'' מסורתי לכל אירוע. קלת משקל ועמידה, מגיעה באריזת מתנה אלגנטית, מושלמת לשימוש יומיומי או כמתנה חגיגית ומרשימה.',
   'Une netla raffinée en polymère, de 14 cm de haut, qui allie beauté et confort. Son design unique, avec des hamsas et une prière, ajoute une touche traditionnelle à chaque occasion. Légère et résistante, elle est livrée dans un élégant coffret cadeau, parfaite pour tous les jours ou comme cadeau de fête.',
   'An elegant polymer washing cup, 14 cm high, combining beauty and comfort. Its unique design with hamsas and a prayer adds a traditional touch to every occasion. Light and durable, it comes in an elegant gift box, perfect for daily use or as a festive gift.',
   137, array['/products/art/uk67553-1.webp','/products/art/uk67553-2.webp','/products/art/uk67553-3.webp','/products/art/uk67553-4.webp']::text[], false, true, 'item', 1900),  -- 54.99 × 2.5
  ('art-UK85284', 'housewarming', array['housewarming','housewarming-netilah','judaica']::text[],
   'נטלה "במבוק עבה" 14 ס"מ - קוד מעורב 16 יח', 'Netla « bambou épais » 14 cm, modèles assortis', '“Thick bamboo” washing cup 14 cm, assorted designs',
   'במבו, במבו', 'bambou', 'bamboo',
   'כוס נטילת ידיים איכותית ואלגנטית, עם שתי ידיות נוחות לאחיזה משני צדדיה. זמינה במגוון דוגמאות מרהיבות - פרחוניות עדינות, נופי ירושלים, שיש זהוב ועוד, עם הכיתוב "נטילת ידים" בעיצוב תואם. מוצר מהודר המוסיף יופי וחן לטקס היומיומי בכל בית.',
   'Une netla de qualité et élégante, avec deux anses confortables de chaque côté. Disponible en plusieurs motifs superbes : fleurs délicates, paysages de Jérusalem, marbre doré et plus encore, avec l’inscription « Netilat yadayim » assortie. Un objet raffiné qui ajoute beauté et charme au rituel quotidien.',
   'A quality, elegant washing cup with two comfortable handles on either side. Available in a range of beautiful designs – delicate florals, Jerusalem views, golden marble and more – with the words “Netilat Yadayim” in a matching style. A refined piece that adds beauty and charm to the daily ritual.',
   32, array['/products/art/uk85284-1.webp','/products/art/uk85284-2.webp','/products/art/uk85284-3.webp','/products/art/uk85284-4.webp','/products/art/uk85284-5.webp','/products/art/uk85284-6.webp','/products/art/uk85284-7.webp','/products/art/uk85284-8.webp','/products/art/uk85284-9.webp','/products/art/uk85284-10.webp','/products/art/uk85284-11.webp']::text[], false, true, 'item', 1901),  -- 12.99 × 2.5
  ('art-UK85151', 'housewarming', array['housewarming','housewarming-netilah','judaica']::text[],
   'נטלה "במבוק עבה" עם הדפסה "פרחים" 14 ס"מ', 'Netla « bambou épais » imprimée « fleurs » 14 cm', '“Thick bamboo” washing cup, “flowers” print, 14 cm',
   'במבו, במבו', 'bambou', 'bamboo',
   'כוס נטילת ידיים מעוצבת בגוון שמנת, עשויה חומר עמיד באיכות גבוהה, מעוטרת בהדפס פרחוני עדין בגווני אפרסק וזהב. הכיתוב "נטילת ידיים" מופיע בבליטה זהובה מרשימה. שתי ידיות רחבות ונוחות לאחיזה מושלמת. מוצר מהודר שישדרג כל פינת נטילה בבית.',
   'Une netla couleur crème en matière résistante de grande qualité, ornée d’un délicat motif floral pêche et or. L’inscription « Netilat yadayim » apparaît en relief doré. Deux larges anses pour une prise parfaite. Un objet raffiné qui embellira tout coin d’ablution de la maison.',
   'A cream washing cup made of a durable, high-quality material, decorated with a delicate floral print in peach and gold. The words “Netilat Yadayim” appear in a striking raised gold. Two wide, comfortable handles for a perfect grip. A refined piece to upgrade any washing corner at home.',
   32, array['/products/art/uk85151-1.webp','/products/art/uk85151-2.webp']::text[], false, true, 'item', 1902),  -- 12.99 × 2.5
  ('art-UK84851', 'housewarming', array['housewarming','housewarming-netilah','judaica']::text[],
   'נטלה "במבוק עבה" עם הדפסה "שיש" 14 ס"מ', 'Netla « bambou épais » imprimée « marbre » 14 cm', '“Thick bamboo” washing cup, “marble” print, 14 cm',
   'במבו, במבו', 'bambou', 'bamboo',
   'כוס נטילת ידיים מהודרת בעיצוב שיש אלגנטי בגוונים לבן-אפור עם ניצוצות זהב, עשויה מבמבוק עמיד באיכות גבוהה. הכיתוב "נטילת ידים" בגימור זהב מוסיף נופך חגיגי. שתי הידיות הרחבות מאפשרות אחיזה נוחה ובטוחה בכל נטילה, מתנה מושלמת לכל בית יהודי.',
   'Une netla raffinée au décor marbré blanc-gris avec des paillettes d’or, en bambou résistant de grande qualité. L’inscription « Netilat yadayim » en finition or ajoute une touche festive. Les deux larges anses offrent une prise sûre et confortable. Un cadeau parfait pour tout foyer juif.',
   'An elegant washing cup with a white-grey marble design and gold flecks, made of durable, high-quality bamboo. The words “Netilat Yadayim” in a gold finish add a festive touch. The two wide handles give a safe, comfortable grip. A perfect gift for any Jewish home.',
   32, array['/products/art/uk84851-1.webp','/products/art/uk84851-2.webp']::text[], false, true, 'item', 1903),  -- 12.99 × 2.5
  ('art-UK84854', 'housewarming', array['housewarming','housewarming-netilah','judaica']::text[],
